begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_function_privilege('authenticated','public.claim_legacy_proposal_number(uuid,uuid,text,timestamptz)','EXECUTE'),'User cannot bypass Edge');
select ok(not has_function_privilege('anon','public.claim_legacy_proposal_number(uuid,uuid,text,timestamptz)','EXECUTE'),'Anonymous claim denied');
select ok(has_function_privilege('service_role','public.claim_legacy_proposal_number(uuid,uuid,text,timestamptz)','EXECUTE'),'Narrow server RPC grant');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.proposal_number_reservations'::regclass),'Forced RLS preserved');
insert into public.organizations(id,legal_name) values('a6102901-0000-4000-8000-000000000001','Legacy QA A'),('a6102901-0000-4000-8000-000000000002','Legacy QA B');
insert into auth.users(id,email) values('b6102901-0000-4000-8000-000000000001','legacy-a@example.invalid'),('b6102901-0000-4000-8000-000000000002','legacy-b@example.invalid'),('b6102901-0000-4000-8000-000000000003','legacy-denied@example.invalid');
insert into public.profiles(id,organization_id,full_name,role_key,status) values
 ('b6102901-0000-4000-8000-000000000001','a6102901-0000-4000-8000-000000000001','QA A','manager','active'),
 ('b6102901-0000-4000-8000-000000000002','a6102901-0000-4000-8000-000000000002','QA B','manager','active'),
 ('b6102901-0000-4000-8000-000000000003','a6102901-0000-4000-8000-000000000001','QA denied','operator','active');
insert into public.financial_institutions(id,organization_id,name) values('c6102901-0000-4000-8000-000000000001','a6102901-0000-4000-8000-000000000001','Legacy QA Bank');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
create function pg_temp.claim(p_sync uuid,p_number text default '2026-0015',p_created timestamptz default '2026-10-29T12:00:00Z',p_actor uuid default 'b6102901-0000-4000-8000-000000000001') returns jsonb language sql as $$select public.claim_legacy_proposal_number(p_actor,p_sync,p_number,p_created)$$;
select is(pg_temp.claim('d6102901-0000-4000-8000-000000000001')->>'proposal_number','2026-0015','Free legacy number preserved exactly');
select is(pg_temp.claim('d6102901-0000-4000-8000-000000000001')->>'proposal_number','2026-0015','Same UUID copied between PCs is idempotent');
select is((select count(*)::integer from public.proposal_number_reservations where organization_id='a6102901-0000-4000-8000-000000000001'),1,'Retry does not consume new number');
select is((select count(*)::integer from public.audit_log where organization_id='a6102901-0000-4000-8000-000000000001' and action='PROPOSAL_LEGACY_NUMBER_CLAIMED'),1,'Retry does not duplicate audit');
select throws_ok($$select pg_temp.claim('d6102901-0000-4000-8000-000000000002')$$,'LC409','legacy_proposal_number_conflict','Different UUID with same number conflicts');
select throws_ok($$select pg_temp.claim('d6102901-0000-4000-8000-000000000001','2026-0016')$$,'LC409','legacy_proposal_number_conflict','Same UUID cannot claim another number');
select throws_ok($$select pg_temp.claim('d6102901-0000-4000-8000-000000000001','2026-0015','2026-10-30T12:00:00Z')$$,'LC409','legacy_proposal_number_conflict','Creation history cannot change on retry');
select is(pg_temp.claim('d6102901-0000-4000-8000-000000000002','2026-0015','2026-10-29T12:00:00Z','b6102901-0000-4000-8000-000000000002')->>'proposal_number','2026-0015','Tenant B can independently claim same human number');
select throws_ok($$select pg_temp.claim('d6102901-0000-4000-8000-000000000003','2027-0015')$$,'LC422','legacy_proposal_year_mismatch','Unknown legacy year must match created_at in Araguaina');
select throws_ok($$select pg_temp.claim('d6102901-0000-4000-8000-000000000003','2026-10000')$$,'DS400','invalid_payload','No five-digit suffix');
select throws_ok($$select pg_temp.claim('d6102901-0000-4000-8000-000000000003','LEGACY/15')$$,'DS400','invalid_payload','Invalid historical identity needs manual review, not renumbering');
select throws_ok($$select pg_temp.claim('d6102901-0000-4000-8000-000000000003','2026-0000')$$,'DS400','invalid_payload','Zero sequence invalid');
select throws_ok($$select pg_temp.claim('d6102901-0000-4000-8000-000000000003','2026-0016',null)$$,'DS400','invalid_payload','No invented creation dates');
select throws_ok($$select pg_temp.claim('d6102901-0000-1000-8000-000000000003')$$,'DS400','invalid_payload','Backfilled sync_id must be valid UUID v4');
select throws_ok($$select pg_temp.claim('d6102901-0000-4000-8000-000000000003','2026-0016','2026-10-29T12:00:00Z','b6102901-0000-4000-8000-000000000003')$$,'DS403','permission_denied','Operator still has no grant');
insert into public.proposal_number_sequences values('a6102901-0000-4000-8000-000000000001',2027,55,now());
select is(pg_temp.claim('d6102901-0000-4000-8000-000000000004','2027-0087','2027-06-01T12:00:00Z')->>'proposal_number','2027-0087','Higher legacy claim preserves 0087');
select is(public.reserve_proposal_number('b6102901-0000-4000-8000-000000000001','d6102901-0000-4000-8000-000000000005','2027-06-01T12:00:00Z')->>'proposal_number','2027-0088','Next central allocation follows highest consumed number');
select is(pg_temp.claim('d6102901-0000-4000-8000-000000000006','2027-0030','2027-06-01T12:00:00Z')->>'proposal_number','2027-0030','Lower historical number can be reconciled');
select is((select last_value from public.proposal_number_sequences where organization_id='a6102901-0000-4000-8000-000000000001' and proposal_year=2027),88,'Lower claim never reduces sequence');
select is(public.reserve_proposal_number('b6102901-0000-4000-8000-000000000001','d6102901-0000-4000-8000-000000000007','2027-06-01T12:00:00Z')->>'proposal_number','2027-0089','Central allocation never fills holes');
select throws_ok($$select pg_temp.claim('d6102901-0000-4000-8000-000000000008','2027-0088','2027-06-01T12:00:00Z')$$,'LC409','legacy_proposal_number_conflict','Central reservation cannot be taken by another legacy UUID');
insert into public.operations(organization_id,operation_number,institution_id) values('a6102901-0000-4000-8000-000000000001','2026-0020','c6102901-0000-4000-8000-000000000001');
select throws_ok($$select pg_temp.claim('d6102901-0000-4000-8000-000000000009','2026-0020')$$,'LC409','legacy_proposal_number_conflict','Never attach to a manual operation by number');
create function pg_temp.payload(p_id uuid,p_number text) returns jsonb language sql as $$select jsonb_build_object('sync_id',p_id,'proposal_number',p_number,'proponent_name','Synthetic applicant','created_at','2026-10-29T12:00:00Z','updated_at','2026-10-29T13:00:00Z','created_by_technician_name','Historical creator','responsible_name','Gustavo','technician_name','Andre','bank','Legacy QA Bank','purpose','QA','total_value','100000.00','fno_value','70000.00','of_value','30000.00')$$;
select throws_ok($$select public.sync_desktop_proposal('b6102901-0000-4000-8000-000000000001',pg_temp.payload('d6102901-0000-4000-8000-000000000001','2026-0015')||'{"created_at":"2026-10-28T12:00:00Z"}')$$,'PN409','proposal_number_reservation_mismatch','Claim creation remains immutable in normal sync');
select is(public.sync_desktop_proposal('b6102901-0000-4000-8000-000000000001',pg_temp.payload('d6102901-0000-4000-8000-000000000001','2026-0015'))->>'result','created','Claim followed by normal 13-field sync');
select is(public.sync_desktop_proposal('b6102901-0000-4000-8000-000000000001',pg_temp.payload('d6102901-0000-4000-8000-000000000001','2026-0015'))->>'result','unchanged','Copied proposal sync does not create another operation');
select is(pg_temp.claim('d6102901-0000-4000-8000-000000000001')->>'proposal_number','2026-0015','Already synchronized identity still idempotent');
select is((select count(*)::integer from public.desktop_proposals where sync_id='d6102901-0000-4000-8000-000000000001'),1,'Exactly one canonical proposal');
select ok(not exists(select 1 from public.audit_log where action='PROPOSAL_LEGACY_NUMBER_CLAIMED' and changes::text ~* 'password|token|secret|total_value|fno_value'),'Claim audit contains only safe identity fields');
select ok(exists(select 1 from public.audit_log where action='PROPOSAL_LEGACY_NUMBER_CLAIMED' and actor_user_id='b6102901-0000-4000-8000-000000000001' and context->>'source'='legacy_migration'),'Claim audit has actor and source');
select * from finish();rollback;
